code:
spm_by_ticker = Transactions.WHERE(
    (LOWER(transaction_type) == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_sell_amount=SUM(Transactions.amount),
    total_costs=SUM(Transactions.tax + Transactions.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    spm=IFF(
        total_sell_amount > 0,
        (total_sell_amount - total_costs) * 100.0 / total_sell_amount,
        0.0
    )
)

spm_by_ticker = Transactions.WHERE(
    (LOWER(transaction_type) == 'sell') &
    (date_time >= DATETIME('now', '-1 month'))
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    total_amount=SUM(Transactions.amount),
    total_tax=SUM(Transactions.tax),
    total_commission=SUM(Transactions.commission)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    spm=(total_amount - (total_tax + total_commission)) / total_amount * 100
)

